1	//! Event bus for dispatching events to multiple consumers.
2	//!
3	//! The `EventBus` is the central event distribution mechanism. Any subsystem
4	//! that produces events calls `emit()`, and all registered consumers receive
5	//! the event. Consumers are independent — they don't know about each other.
6	//!
7	//! # Primary consumers
8	//!
9	//! 1. **Event logger** — writes all events to JSONL for debugging/auditing
10	//! 2. **State recorder** — updates persistent state on step completion
11	//!    (currently called directly; will be converted to EventConsumer)
12	//! 3. **Presenter** — shows real-time terminal output
13	//!    (currently called directly; will be converted to EventConsumer)
14	
15	use super::events::{BivvyEvent, EventConsumer};
16	
17	/// Central event dispatcher that fans out events to registered consumers.
18	///
19	/// # Usage
20	///
21	/// ```
22	/// use bivvy::logging::bus::EventBus;
23	/// use bivvy::logging::{BivvyEvent, EventConsumer};
24	///
25	/// let mut bus = EventBus::new();
26	///
27	/// // In production, register the EventLogger:
28	/// // bus.add_consumer(Box::new(logger));
29	///
30	/// bus.emit(&BivvyEvent::StepStarting {
31	///     name: "build".to_string(),
32	/// });
33	/// ```
34	pub struct EventBus {
35	    consumers: Vec<Box<dyn EventConsumer>>,
36	}
37	
38	impl EventBus {
39	    /// Create a new event bus with no consumers.
40	    pub fn new() -> Self {
41	        Self {
42	            consumers: Vec::new(),
43	        }
44	    }
45	
46	    /// Register an event consumer.
47	    ///
48	    /// Consumers are called in registration order for each event.
49	    pub fn add_consumer(&mut self, consumer: Box<dyn EventConsumer>) {
50	        self.consumers.push(consumer);
51	    }
52	
53	    /// Dispatch an event to all registered consumers.
54	    pub fn emit(&mut self, event: &BivvyEvent) {
55	        for consumer in &mut self.consumers {
56	            consumer.on_event(event);
57	        }
58	    }
59	
60	    /// Returns the number of registered consumers.
61	    pub fn consumer_count(&self) -> usize {
62	        self.consumers.len()
63	    }
64	}
65	
66	impl Default for EventBus {
67	    fn default() -> Self {
68	        Self::new()
69	    }
70	}
71	
