241	    /// Get the local path for a repository.
242	    ///
243	    /// Uses a hash of the URL to create a deterministic, unique path.
244	    pub fn repo_path(&self, url: &str) -> PathBuf {
245	        let hash = Sha256::digest(url.as_bytes());
246	        let hash_str = hex::encode(&hash[..8]);
247	        self.clone_dir.join(hash_str)
248	    }
