        let registry = Registry::new(None).unwrap();

        let templates_with_requires: Vec<String> = registry
            .all_template_names()
            .into_iter()
            .filter(|name| {
                registry
                    .get(name)
                    .map(|t| !t.step.requires.is_empty())
                    .unwrap_or(false)
            })
            .collect();

        // This list must match the count in builtin_templates_declare_correct_requires.
