/// Snapshot of `bivvy cache clear --help`.
#[test]
fn cache_clear_help_snapshot() {
    let home = TempDir::new().unwrap();
    let (stdout, _stderr, code) =
        run_cache_isolated(&["cache", "clear", "--help"], home.path());
