//! Cache storage implementation.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Write data to a file atomically by writing to a temporary file in the
/// same directory and then renaming. This prevents corruption when multiple
/// processes write to the same cache entry concurrently.
fn atomic_write(path: &Path, data: &[u8]) -> io::Result<()> {
    let dir = path.parent().unwrap_or(Path::new("."));
    let mut tmp_name = std::ffi::OsString::from(".tmp.");
    let mut buf = [0u8; 8];
    crate::sys::random_bytes(&mut buf);
    tmp_name.push(hex::encode(buf));
    let tmp_path = dir.join(tmp_name);

    fs::write(&tmp_path, data)?;
    fs::rename(&tmp_path, path).map_err(|e| {
        let _ = fs::remove_file(&tmp_path);
        e
    })
}

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

